// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { FileUploaderButton } from 'carbon-components-react';

function App() {
  return (
    <div style={{ padding: '3em', display: 'flex', justifyContent: 'center', backgroundColor: '#fff' }}>
      {/** This will render a <label role="button"> internally **/}
      <FileUploaderButton
        labelText="Add files"
        multiple={false}
        accept={['.png', '.jpg', '.gif']}
        onChange={evt => console.log('files selected ->', evt.target.files)}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
